<script setup lang="ts">
import {ref} from 'vue'
import {useI18n} from 'vue-i18n'
import {copy,validMoney} from '../payrollUi'
import {settlementAmount,settlementIssue} from '../supplemental'
import type {CompanySdl,CompanySdlEvidence} from '../supplemental'
import type {Option} from '../types'
const props=defineProps<{page:CompanySdl;employees:Option[];headOffice:boolean;locked:boolean}>(),emit=defineEmits<{save:[body:CompanySdlEvidence]}>(),{locale}=useI18n(),en=()=>locale.value.startsWith('en'),x=(z:string,e:string)=>en()?e:z,money=(v:string|null|undefined)=>settlementAmount(v,en()),editing=ref(false),error=ref(''),draft=ref<CompanySdlEvidence>(copy(props.page.evidence||{commandId:'',expectedVersion:props.page.version,evidenceReference:'',employeeIds:[],recognisedSdl:null,remittedSdl:null}))
function save(){if(props.locked||!props.headOffice||!props.page.writable)return;const d=copy(draft.value);d.recognisedSdl=d.recognisedSdl||null;d.remittedSdl=d.remittedSdl||null;if(!d.evidenceReference.trim()||!d.employeeIds.length||[d.recognisedSdl,d.remittedSdl].some(v=>v!==null&&!validMoney(v))){error.value=x('核对公司完整员工范围及原责任／实缴凭证；未知留空。','Review the complete employee scope and opening liability / remittance evidence; leave unknown values blank.');return}d.commandId=crypto.randomUUID();d.expectedVersion=props.page.version;emit('save',d)}
</script>
<template><section class="wf-section"><h3>{{x('公司月SDL与独立舍入','Company monthly SDL and separate rounding')}} · {{page.month}}</h3><dl class="wf-details"><dt>{{x('公司目标／原已确认／累计实缴','Company target / recognised / actually remitted')}}</dt><dd>{{money(page.target)}} / {{money(page.recognised)}} / {{money(page.remitted)}}</dd><dt>{{x('公司责任修订／待缴或待退','Company liability revision / remittance or refund balance')}}</dt><dd>{{money(page.liabilityDelta)}} / {{money(page.remittanceBalance)}}</dd><dt>{{x('个人合计／公司舍入调整','Individual total / company rounding adjustment')}}</dt><dd>{{money(page.individualTotal)}} / {{money(page.roundingAdjustment)}}</dd></dl><p>{{x('公司舍入独立保存，不将尾差分配给任意员工。','Company rounding remains separate and is not assigned to an arbitrary employee.')}}</p><p v-for="(code,i) in page.issues" :key="i" role="alert">{{settlementIssue(code,en())}} ({{code}})</p><button v-if="headOffice&&page.writable&&!editing" :disabled="locked" @click="editing=true">{{x('维护外部公司月凭证','Edit external company month evidence')}}</button><form v-if="editing" @submit.prevent="save"><fieldset :disabled="locked"><p>{{x('范围为该公司该月全部实际员工；普通已冻结工资自动保留，外部实际须有完整凭证。','Scope includes all actual employees for the company month. Frozen payroll is retained automatically; external actuals require complete evidence.')}}</p><label v-for="e in employees" :key="e.id"><input v-model="draft.employeeIds" type="checkbox" :value="e.id">{{e.name}}</label><label>{{x('公司月完整性凭证','Company month completeness evidence')}}<textarea v-model="draft.evidenceReference" required :aria-label="x('公司月完整性凭证','Company month completeness evidence')"/></label><label>{{x('外部原公司SDL责任','Opening company SDL recognised')}}<input v-model="draft.recognisedSdl" inputmode="decimal"></label><label>{{x('外部原公司SDL实缴','Opening company SDL remitted')}}<input v-model="draft.remittedSdl" inputmode="decimal"></label><button type="submit" :disabled="locked">{{x('保存公司SDL凭证','Save company SDL evidence')}}</button><button type="button" :disabled="locked" @click="editing=false">{{x('取消','Cancel')}}</button></fieldset><p v-if="error" role="alert">{{error}}</p></form></section></template>
